<script setup lang="ts">
import {computed,ref} from 'vue'
import {useResource,useTask} from '../composables/useData'
import {service} from '../services'
import {useAuth} from '../stores/auth'
import {formatDate} from '../composables/useData'
import type {Gap} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import Icon from '../components/Icon.vue'
const auth=useAuth(),gaps=useResource('gaps'),task=useTask(),filter=ref('unresolved'),query=ref(''),dialog=ref(false),selected=ref<Gap>()
const rows=computed(()=>gaps.items.value.filter(g=>(!filter.value||g.status===filter.value)&&(!query.value||g.question.includes(query.value))))
async function update(gap:Gap,status:Gap['status']){await task.run(async()=>{await service.save('gaps',{id:gap.id,status});await gaps.load()},'缺口状态已更新')}
function detail(gap:Gap){selected.value=gap;dialog.value=true}
</script>
<template><PageHeader title="知识缺口" description="关注未命中或置信度不足的问题，按提问频次补齐知识。"><button class="btn quiet" @click="gaps.load" :disabled="gaps.loading.value"><Icon name="refresh"/>刷新</button></PageHeader><form class="filters" @submit.prevent><label class="search"><Icon name="search"/><input v-model="query" placeholder="搜索未被回答的问题" aria-label="搜索知识缺口"></label><select v-model="filter" aria-label="知识缺口状态"><option value="unresolved">待补充</option><option value="resolved">已解决</option><option value="ignored">已忽略</option><option value="">全部状态</option></select></form><LoadState :loading="gaps.loading.value" :error="gaps.error.value" :empty="!rows.length" empty-text="当前没有符合条件的知识缺口。" @retry="gaps.load"><div class="table-wrap"><table class="data-table"><thead><tr><th>问题模式</th><th class="num">提问频次</th><th>最近提问</th><th>状态</th><th>处理</th></tr></thead><tbody><tr v-for="gap in rows" :key="gap.id"><td><button class="identity gap-question" @click="detail(gap)">{{gap.question}}</button><span class="sub">{{gap.samples.length}} 条问题样本</span></td><td class="num">{{gap.count}}</td><td class="num">{{formatDate(gap.lastAskedAt)}}</td><td><span class="status" :class="gap.status==='resolved'?'success':gap.status==='unresolved'?'warning':''">{{gap.status==='resolved'?'已解决':gap.status==='unresolved'?'待补充':'已忽略'}}</span></td><td><div class="row-actions"><RouterLink v-if="gap.status==='unresolved'&&auth.has('knowledge.create')" :to="`/knowledge/units/new?gap=${gap.id}`" class="text-button">补充知识</RouterLink><RouterLink v-if="gap.unitId" :to="`/knowledge/units/${gap.unitId}`" class="text-button">关联知识</RouterLink><button v-if="gap.status==='unresolved'" class="text-button" :disabled="task.busy.value" @click="update(gap,'ignored')">忽略</button><button v-if="gap.status==='ignored'" class="text-button" :disabled="task.busy.value" @click="update(gap,'unresolved')">重新打开</button></div></td></tr></tbody></table></div></LoadState><div class="notice" style="margin-top:20px">权限不足与知识缺口分别处理。因无权访问而未能作答的问题，不会自动计入缺口。</div><el-dialog v-model="dialog" title="问题样本" width="580px"><template v-if="selected"><h2>{{selected.question}}</h2><p class="small faint" style="margin-top:12px">共提问 {{selected.count}} 次 · 最近 {{formatDate(selected.lastAskedAt)}}</p><ul class="sample-list"><li v-for="sample in selected.samples" :key="sample">{{sample}}</li></ul><RouterLink v-if="selected.status==='unresolved'&&auth.has('knowledge.create')" :to="`/knowledge/units/new?gap=${selected.id}`" class="btn primary" @click="dialog=false">创建关联知识</RouterLink></template></el-dialog></template>
<style scoped>.gap-question{border:0;background:none;padding:0;text-align:left;cursor:pointer;font:inherit}.gap-question:hover{color:var(--accent)}.sample-list{padding-left:20px;color:var(--muted);line-height:2;margin:24px 0;font-size:13px}</style>
